import re

def parse_version(v):
    # regex per spec simplified
    m = re.fullmatch(r'(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?', v)
    if not m:
        raise ValueError(f'Invalid version: {v}')
    major, minor, patch, prerelease, build = m.groups()
    return int(major), int(minor), int(patch), prerelease, build

def split_ids(s):
    if s is None:
        return []
    return s.split('.')

def compare_pre(a_ids, b_ids):
    for aid, bid in zip(a_ids, b_ids):
        a_digit = aid.isdigit()
        b_digit = bid.isdigit()
        if a_digit and b_digit:
            ai = int(aid)
            bi = int(bid)
            if ai < bi:
                return -1
            if ai > bi:
                return 1
        elif a_digit:
            return -1  # numeric lower
        elif b_digit:
            return 1
        else:
            if aid < bid:
                return -1
            if aid > bid:
                return 1
    # all equal so far
    if len(a_ids) < len(b_ids):
        return -1
    if len(a_ids) > len(b_ids):
        return 1
    return 0

def semver_compare(a, b):
    ma, mi, pa, pre_a, build_a = parse_version(a)
    mb, mi_b, pb, pre_b, build_b = parse_version(b)
    # compare major/minor/patch
    if ma < mb: return -1
    if ma > mb: return 1
    if mi < mi_b: return -1
    if mi > mi_b: return 1
    if pa < pb: return -1
    if pa > pb: return 1
    # core equal
    a_has = pre_a is not None
    b_has = pre_b is not None
    if not a_has and b_has:
        return 1  # a without pre-release higher
    if a_has and not b_has:
        return -1
    if a_has and b_has:
        res = compare_pre(split_ids(pre_a), split_ids(pre_b))
        if res != 0:
            return res
    # build ignored
    return 0

